package net.zartra.gui;
import org.bukkit.*;import org.bukkit.enchantments.Enchantment;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import java.util.*;
final class MenuItem {String material;int data;int amount;String name;List<String> lore;boolean glow;boolean hideEnchantments;boolean unbreakable;int customModelData=-1;String headOwner="";String leatherColor="";String potionData="";final Map<String,Integer> enchantments=new TreeMap<String,Integer>();boolean closeAfterAction;long cooldown;int priority;String fallbackMaterial="";MenuAction action;final ConditionSet conditions=new ConditionSet();final Map<MenuClickType,List<ActionEntry>> actions=new EnumMap<MenuClickType,List<ActionEntry>>(MenuClickType.class);MenuItem(ItemStack stack,MenuAction legacy){material=CompatMaterial.name(stack.getType());data=stack.getDurability();amount=Math.max(1,stack.getAmount());ItemMeta m=null;try{if(Bukkit.getServer()!=null)m=stack.getItemMeta();}catch(Exception ignored){}name=m!=null&&m.hasDisplayName()?m.getDisplayName():null;lore=m!=null&&m.hasLore()?new ArrayList<String>(m.getLore()):new ArrayList<String>();glow=m!=null&&m.hasEnchants();action=legacy;}ItemStack stack(){ItemStack out=new ItemStack(CompatMaterial.find(material),amount,(short)data);ItemMeta meta=out.getItemMeta();if(meta!=null){if(name!=null)meta.setDisplayName(Chat.c(name));if(lore!=null&&!lore.isEmpty()){List<String>x=new ArrayList<String>();for(String s:lore)x.add(Chat.c(s));meta.setLore(x);}if(glow)meta.addEnchant(Enchantment.DURABILITY,1,true);for(Map.Entry<String,Integer>e:enchantments.entrySet())try{meta.addEnchant(Enchantment.getByName(e.getKey()),e.getValue(),true);}catch(Exception ignored){}out.setItemMeta(meta);}return out;}List<ActionEntry> actions(MenuClickType type){List<ActionEntry> list=actions.get(type);if(list==null){list=new ArrayList<ActionEntry>();actions.put(type,list);}Collections.sort(list,new Comparator<ActionEntry>(){public int compare(ActionEntry a,ActionEntry b){return a.order-b.order;}});return list;}void migrateLegacy(){if(action!=null&&actions.isEmpty()){ActionEntry x=new ActionEntry();x.type=action.type.name();x.value=action.value;x.order=0;actions(MenuClickType.LEFT).add(x);}action=null;}}